/* Fixed trace viewer. Graph explanations never fabricate runtime tensor values. */
'use strict';
const $ = s => document.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = x => typeof x !== 'number' ? esc(x) : (!Number.isFinite(x)?String(x):Number.isInteger(x)?String(x):Math.abs(x)<.0001?x.toExponential(3):x.toPrecision(5));
const shape = a => `[${(a || []).join(', ')}]`;
const base = 'model.language_model';
const checkpoint = 'https://huggingface.co/tiny-random/glm-5.3-flash/blob/aeb642e89f4bb6b55b186ca440edff0acb9ee9f5/';
let trace, graphNodes=[];
const state = {step:-1,tab:'prepare',layer:0,sub:'overview',node:null,token:10,query:0,search:'',scope:'',range:null,page:0,op:0};
const opCache = new Map();
const phase = () => trace.steps[Math.max(0,state.step)];
const prefix = () => `${base}.layers.${state.layer}`;
const kind = l => [3,7].includes(l)?'DSA':'KDA';
const phaseName = i => i<0?'Prompt → tokens':i===0?'Prefill':`Decode ${i}`;
const mod = path => phase().modules.find(m=>m.path===path);
const fn = name => phase().functions.find(f=>f.scope===prefix()+'.self_attn' && f.function.includes(name));
function panel(title,body,tag='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><h2>${title}</h2>${tag}</div><div class="panel-body">${body}</div></section>`;}
const tag = (text,cls='measured')=>`<span class="tag ${cls}">${text}</span>`;
function layerSelect(){return `<select id="layer-select" aria-label="选择主干层">${Array.from({length:8},(_,l)=>`<option value="${l}" ${state.layer===l?'selected':''}>Layer ${l} · ${kind(l)} · ${l<3?'Dense':'MoE'}</option>`).join('')}</select>`;}
function setPhase(i){state.step=i;state.query=0;state.node=null;state.range=null;state.op=0;state.page=0;if(i<0)state.tab='prepare';else if(state.tab==='prepare')state.tab='graph';render();}
function setTab(tab){state.tab=tab;if(tab!=='prepare'&&state.step<0)state.step=0;render();}
function render(){
 $('#session-meta').innerHTML=`<span>MODEL <strong>tiny / 8 layers</strong></span><span>PRECISION <strong>FP32 reference</strong></span><span>PROMPT <strong>18 tokens</strong></span><span>VOCAB <strong>154,880</strong></span><span>REV <strong>${trace.revision.slice(0,8)}</strong></span>`;
 $('#phase-label').textContent=state.step<0?'00 / 准备输入':`${String(state.step+1).padStart(2,'0')} / ${phaseName(state.step)} · 输入 ${phase().input_ids.length} token · 上下文 ${phase().context_length}`;
 $('#previous-step').disabled=state.step<0;$('#next-step').disabled=state.step===3;
 $('#timeline').innerHTML=[-1,0,1,2,3].map(i=>`<button data-step="${i}" class="${state.step===i?'active':''}"><span class="step-number">${String(i+1).padStart(2,'0')}</span><b>${phaseName(i)}</b><small>${i<0?'messages → IDs':`T=${trace.steps[i].input_ids.length} · L=${trace.steps[i].context_length}`}</small></button>`).join('');
 $('#generated-tokens').innerHTML='<span class="generated-label">实际生成</span>'+trace.steps.map((s,i)=>`<button data-step="${i}" title="token ID ${s.chosen.id}" class="generated-token ${i>state.step?'future':''} ${i===state.step?'current':''}">${esc(s.chosen.text)}</button>`).join('')+'<span class="generated-end">随机权重输出 · 4 token 后停止</span>';
 $('#prepare-nav').classList.toggle('active',state.step<0);
 $('#step-nav').innerHTML=trace.steps.map((s,i)=>`<button class="nav-item ${i===state.step?'active':''}" data-step="${i}">0${i+1}<span>${phaseName(i)}</span></button>`).join('');
 $('#layer-nav').innerHTML=Array.from({length:8},(_,l)=>`<button data-layer="${l}" class="layer-button ${kind(l).toLowerCase()} ${l===state.layer?'active':''}">L${l} · ${kind(l)} <span>${l<3?'Dense':'MoE'}</span></button>`).join('');
 document.querySelectorAll('.tabs [data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));
 if(state.tab==='prepare')renderPrepare();if(state.tab==='graph')renderGraph();if(state.tab==='state')renderState();if(state.tab==='ops')renderOps();if(state.tab==='verify')renderVerify();
}
function renderPrepare(){
 const template=trace.template.split(/(\[gMASK\]|<[^>]+>)/g).map(t=>/^(\[gMASK\]|<)/.test(t)?`<span class="special">${esc(t)}</span>`:esc(t)).join('');
 $('#view').innerHTML=`<div class="prepare-grid">${panel('01 · 用户消息',`<div class="message"><small>USER</small>${esc(trace.messages[0].content)}</div><p class="muted">这里展示一次已经执行的固定示例。模板与 tokenizer 来自同一 checkpoint。</p><div class="template-options">reasoning_effort = "low"<br>add_generation_prompt = true<br>batch_size = 1 · padding = none</div>`)}${panel('02 · 原生对话模板',`<div class="template-string">${template}</div><div class="template-options">系统部分由模板注入；助手前缀与 &lt;think&gt; 已在输入中。<br>紫色表示模板控制文本，不等于 tokenizer 的 special-token 标记。</div>`,tag('真实模板'))}<section class="panel full-width"><div class="panel-head"><h2>03 · Tokenizer → 18 个 token</h2>${tag('点击 token 查看编码')}</div><div class="token-grid">${trace.prompt_tokens.map((t,i)=>`<button class="token ${t.special?'special':''} ${state.token===i?'selected':''}" data-token="${i}"><small>POS ${String(i).padStart(2,'0')}</small><b>${esc(t.text)}</b><em>${t.id}</em></button>`).join('')}</div><div id="token-details" class="token-details"></div></section>${panel('04 · 输入张量',`<div class="tensor-preview">input_ids · int64 [1, 18]<br>${shape(trace.steps[0].input_ids)}<br><br>attention_mask · int64 [1, 18]<br>${shape(trace.steps[0].attention_mask)}<br><br>position_ids · int64 [1, 18]<br>${shape(trace.steps[0].position_ids)}</div><button class="primary-button" data-step="0">进入 Prefill，追踪第一个新 token →</button>`,tag('真实值'),'full-width')}</div>`;
 showToken();
}
function showToken(){const t=trace.prompt_tokens[state.token];$('#token-details').innerHTML=`position=${state.token} · ID=${t.id} · special=${t.special}<br>tokenizer piece: ${esc(JSON.stringify(t.piece))} → decoded: ${esc(JSON.stringify(t.text))}`;}
function heatmap(rows,label){
 if(!rows?.length||!rows[0]?.length)return '';
 const max=Math.max(...rows.flat().filter(x=>typeof x==='number').map(Math.abs),1e-20);
 return `<div class="heatmap" style="grid-template-columns:repeat(${rows[0].length},1fr)">${rows.map((r,i)=>r.map((v,j)=>{const n=typeof v==='number'?v:0;return `<span class="heat-cell" title="[${i}, ${j}] = ${esc(v)}" style="background:hsla(${n<0?268:165},60%,${23+Math.min(1,Math.abs(n)/max)*42}%,${n===0?.18:1})"></span>`;}).join('')).join('')}</div><div class="heat-caption">${label} · 悬停查看坐标与值 · 色阶按本图最大绝对值</div>`;
}
function sampleCard(s,label){if(!s)return '';if(s.values_omitted)return `<div class="io-block"><div class="io-caption">${label} · PARAMETER</div><div class="io-shape">${shape(s.shape)} · ${esc(s.dtype)}</div><div class="inspect-path">${esc(s.parameter)}</div><p class="heat-caption">仅保留参数名与尺寸；权重值未保存。</p></div>`;return `<div class="io-block"><div class="io-caption">${label}</div><div class="io-shape">${shape(s.shape)} · ${esc(s.dtype)} · ${s.numel.toLocaleString()} elements</div>${s.numel?`<div class="stats-grid">${['min','max','mean','norm'].map(k=>`<div class="stat"><small>${k} · 全张量</small>${fmt(s[k])}</div>`).join('')}</div>${heatmap(s.tile,'leading tile · 最多 8 行 × 12 列')}<details><summary>前 24 个标量</summary><div class="sample-values">${s.sample.map(fmt).join(', ')}</div></details>${s.last_row?`<details><summary>最后一行的前 24 个标量</summary><div class="sample-values">${s.last_row.map(fmt).join(', ')}</div></details>`:''}`:'<p class="heat-caption">空张量：本配置 RoPE 维度为 0。</p>'}</div>`;}
// Node x/y coordinates describe a readable explanation. Only references to trace
// records supply measured samples; other nodes are explicitly marked CODE.
function graphSpec(){
 const p=prefix(),T=phase().input_ids.length,L=phase().context_length,S=`[1, ${T}, 128]`,H=`[1, ${T}, 4, 128]`;let nodes=[],edges=[],note='';
 const add=(id,title,sh,x,y,ref=null,desc='',color='',formula='')=>{const n={id,title,sh,x,y,w:220,h:64,ref,desc,color,formula};nodes.push(n);return n;};
 const m=(id,title,path,x,y,desc='',color='')=>{const r=mod(path);return add(id,title,r?shape(r.output_samples[0]?.shape):'—',x,y,r,desc,color);};
 const d=(id,title,sh,x,y,desc='',color='',formula='')=>add(id,title,sh,x,y,null,desc,color,formula);
 const e=(a,b,label='',style='',via=null)=>edges.push({a,b,label,style,via});
 if(state.sub==='overview'){
  m('embed','Token embedding',base+'.embed_tokens',280,25,'查表得到 token 表示。输入是整数 ID；输出是 FP32 激活。');
  d('expand','复制为 4 路 residual streams',H,280,125,'unsqueeze → expand → contiguous。每个 token 的四路初始值相同。','purple');e('embed','expand');
  for(let l=0;l<8;l++){m('l'+l,`Layer ${l} · ${kind(l)} + ${l<3?'Dense':'MoE'}`,`${base}.layers.${l}`,280,225+l*100,'点击左侧层号，展开该层的内部数据流。',kind(l)==='DSA'?'blue':'');e(l?'l'+(l-1):'expand','l'+l);}
  m('head','HyperHead · mean(streams)',base+'.hc_head',280,1025,'沿 stream 轴做不带权重的均值。','purple');m('norm','Final RMSNorm',base+'.norm',280,1125);m('lm','最后位置 → LM head','lm_head',280,1225,'本次 logits_to_keep=1，只对最后位置计算 logits。');d('pick','argmax → 新 token',`ID ${phase().chosen.id} · ${phase().chosen.text}`,280,1325,'greedy 选择原始 logits 最大项。不做随机采样，不运行 MTP。','amber');e('l7','head');e('head','norm');e('norm','lm','slice last position');e('lm','pick');
  d('vision','Vision branch · 未执行','text-only prompt',25,25,'权重存在，但这个输入没有图像。','state');d('mtp','MTP · 未执行','ordinary autoregression',535,1325,'加载器忽略 layer 8 的 26 个辅助键；当前主干仅 layer 0–7。','state');
  note='这张图展示本次文本路径的完整主干。每个层节点可读取输入输出；侧栏选择层号后可逐级展开。';
 }else if(state.sub==='layer'){
  d('in','Residual streams · X',H,280,25,'四路激活沿层向下流动。它们不是跨 decode 步保存的缓存。','purple');
  m('hc1','Attention mHC',p+'.attn_hc',280,125,'输出顺序：post [1,T,4]，comb [1,T,4,4]，collapsed [1,T,128]。','purple');m('n1','Input RMSNorm',p+'.input_layernorm',280,225);m('att',kind(state.layer)+' attention',p+'.self_attn',280,325,'切换“Attention”查看 Q/K/V、门控与缓存分支。',kind(state.layer)==='DSA'?'blue':'');
  d('add1','mHC residual recombine',H,280,425,'使用原始 X 与当前 attention 输出重新组合四路。','purple','X′ = post[..., :, None] × attn[..., None, :]\n   + combᵀ @ X');
  m('hc2','FFN mHC',p+'.ffn_hc',280,525,'FFN 有自己独立的 mHC 参数；不是复用 attention mHC。','purple');m('n2','Post-attention RMSNorm',p+'.post_attention_layernorm',280,625);m('ffn',state.layer<3?'Dense gated MLP':'MoE · 8/32 + shared',p+'.mlp',280,725,'切换“FFN”展开投影、门控、路由与共享专家。','amber');m('out','mHC recombine → layer out',p,280,825,'第二次 residual recombine；这里的实际采样来自整个 layer 的输出。','purple');
  ['in','hc1','n1','att','add1','hc2','n2','ffn','out'].forEach((id,i,a)=>{if(i)e(a[i-1],id,i===2||i===6?'collapsed':'');});
  e('in','add1','residual X','',60);e('hc1','add1','post / comb','state',690);e('add1','out','residual X′','',60);e('hc2','out','post / comb','state',690);
  note='实线为激活依赖，虚线为旁路参数／状态依赖。mHC 内部返回 3 个张量，可在右侧逐个展开。';
 }else if(state.sub==='attention'&&kind(state.layer)==='KDA'){
  m('q','Q projection',p+'.self_attn.q_proj',25,25);m('k','K projection',p+'.self_attn.k_proj',280,25);m('v','V projection',p+'.self_attn.v_proj',535,25);
  d('cat','cat(Q,K,V) → transpose',`[1, 24576, ${T}]`,280,125,'沿通道拼接三路 8192，再转为卷积布局。');e('q','cat');e('k','cat');e('v','cat');
  const conv=fn('causal_conv1d');add('conv',state.step===0?'Causal Conv1d + SiLU':'Conv cache update + SiLU',shape(conv?.outputs[0]?.shape),280,225,conv,'depthwise kernel=4；缓存保存卷积前的 QKV，而非卷积输出。');e('cat','conv');
  d('split','split → reshape Q / K / V',`each [1, ${T}, 64, 128]`,280,325,'Q、K 在 KDA 内做 FP32 L2 normalization；Q 再乘 128⁻½。');e('conv','split');
  m('forget','Forget gate · g',p+'.self_attn.forget_gate',25,425,'f_a → f_b → dt_bias → exp(A_log) → sigmoid；g=-5×sigmoid(...)。');m('beta','Beta projection',p+'.self_attn.b_proj',535,425,'输出先是 logits，在 KDA 前取 sigmoid 得 β [1,T,64]。');
  const kda=fn('kimi_delta_attention');add('kda',state.step===0?'Chunk KDA · reference':'Recurrent KDA · reference',shape(kda?.outputs[0]?.shape),280,525,kda,'prefill 的实际实现按 64-token chunk 组织并内部 padding。decode 使用递归实现；下面公式解释逐 token 的数学状态更新。','','S̃ = exp(g)[..., :, None] × Sprev\nm = Σkey (S̃ × k[..., :, None])\nδ = β × (v − m)\nSnew = S̃ + k[..., :, None] × δ[..., None, :]\ny = Σkey (Snew × q[..., :, None])');e('split','kda');e('forget','kda','g');e('beta','kda','sigmoid → β');
  d('cache','Recurrent state · read / write','[1, 64, 128, 128]',25,625,'prefill 从零态开始；decode 读取上一轮状态。固定大小不意味着内容不变。','state');e('cache','kda','Sprev','state');e('kda','cache','Snew','state');
  m('ga','Output gate · g_a',p+'.self_attn.g_a_proj',535,625);m('gb','Output gate · g_b',p+'.self_attn.g_b_proj',535,725,'reshape [1,T,64,128]，传入 RMSNormGated。');e('ga','gb');
  m('norm','RMSNorm × sigmoid(gate)',p+'.self_attn.o_norm',280,825,'输出门使用 sigmoid，不是 SiLU。先 RMS 归一化每个 head，再乘 sigmoid gate。');e('kda','norm');e('gb','norm','gate');m('out','Flatten → output projection',p+'.self_attn.o_proj',280,925,'64×128=8192，投影回 hidden_size=128。');e('norm','out');
  note='Q/K/V、forget、β 和 output gate 分支都读取同一个归一化后的层输入。为保持图可读，共同输入在分支顶端隐去；每个模块的真实输入仍可点击查看。卷积状态见“状态与路由”。';
 }else if(state.sub==='attention'){
  m('qa','Q low-rank projection',p+'.self_attn.q_a_proj',25,25);m('qn','Q RMSNorm',p+'.self_attn.q_a_layernorm',25,125);m('qb','Q head projection',p+'.self_attn.q_b_proj',25,225,'reshape → [1,64,T,32]；实际 head dim = nope32 + rope0。');e('qa','qn');e('qn','qb');
  m('ka','KV compressed projection',p+'.self_attn.kv_a_proj_with_mqa',280,25,'split: latent256 + rope0。');m('kn','KV latent RMSNorm',p+'.self_attn.kv_a_layernorm',280,125);d('cache','Append compressed cache',`K [1,1,${L},256] · V […,0]`,280,225,'cache.keys 存 latent；cache.values 存空的 k_rot，并不是展开后的 value。','state');m('kb','Expand KV for attention',p+'.self_attn.kv_b_proj',280,325,'每个历史位置展开 64×(32+256)。再分成 K[1,64,L,32] 与 V[1,64,L,256]。');e('ka','kn');e('kn','cache');e('cache','kb');
  m('idx','DSA indexer',p+'.self_attn.indexer',535,225,'输入 x 与 Q 的低秩归一化表示；内部 k projection+LayerNorm，Q projection，压缩门与 head weights。当前实现没有对 indexer 应用 RoPE。','blue');e('qn','idx','q residual','',100);d('pool','Raw indices · output view',`[1, ${T}, 131]`,535,325,'索引器内部：每 4 token 按通道门控池化，32 个池候选上限映射到 128 raw slots，再加最多 3 个尾部 token。-1 为无效占位。这里只拆解语义，真实 ATen 序列见算子页。','blue');e('idx','pool');
  d('mask','Causal + sparse mask',`[1, 1, ${T}, ${L}]`,535,425,'只有已经可见且被选中的 raw index 放行；被屏蔽位置为 -Infinity。','blue');e('pool','mask');
  d('scores','QKᵀ × 32⁻½ + mask',`[1, 64, ${T}, ${L}]`,280,525,'实际 eager backend 先物化 dense scores，再叠加稀疏／因果 mask。不要把语义稀疏选择误画成稀疏 GPU kernel。','blue');e('qb','scores','Q','',65);e('kb','scores','K');e('mask','scores','mask');
  d('softmax','FP32 softmax',`[1, 64, ${T}, ${L}]`,280,625,'“状态与路由”保存本次 head 0 的完整注意力矩阵。','blue');d('av','Attention @ V → transpose',`[1, ${T}, 64, 256]`,280,725,'加权求和后恢复 token-major 布局。','blue');m('out','Flatten 16384 → O projection',p+'.self_attn.o_proj',280,825);e('scores','softmax');e('softmax','av');e('kb','av','V','',50);e('av','out');
  note='Q、KV 和 indexer 分支读取同一层输入。DSA 索引器内部算子可从节点跳转；head 0 注意力矩阵和全部 raw indices 在“状态与路由”中。';
 }else if(state.sub==='indexer'){
  const dl=[3,7].includes(state.layer)?state.layer:3,ip=`${base}.layers.${dl}.self_attn.indexer`,P=Math.floor(L/4);
  m('q','Q projection from q_resid',ip+'.wq_b',25,25,'reshape → [1,T,32,128]。q_resid 来自主 attention 的低秩 Q RMSNorm。','blue');
  m('k','Key projection from x',ip+'.wk',280,25,'单个 index key head，维度 128。','blue');m('kn','Key LayerNorm',ip+'.k_norm',280,125,'这里是带 bias 的 LayerNorm，不是 RMSNorm。','blue');e('k','kn');
  d('gate','Compression gate · F.linear',`[1, ${T}, 128]`,535,125,'输入 x 与 index_kpool_compress_gate 参数矩阵相乘；这是池化内每个通道的打分。','blue');
  d('pack','Pack + append indexer cache',`[1, ${L}, 257]`,280,225,'concat(key128, gate128, valid1)，更新本层 indexer_keys。','state');e('kn','pack');e('gate','pack');
  d('pool','Group 4 → softmax → pool',`[1, ${P}, 128]`,280,325,'本例无 padding，完整池数 floor(L/4)。gate 加每个池内 offset 的 APE，再沿池内 4 个 token 做逐通道 softmax，加权 key 求和；不完整池从池候选中删除。','blue','p = softmax(gate + APE, dim=pool_token)\npooled_key = Σtoken p × key');e('pack','pool');
  d('scores','Q @ pooled Kᵀ → ReLU',`[1, ${T}, 32, ${P}]`,280,425,'先乘 head_dim⁻½ = 128⁻½，再 ReLU。','blue');e('q','scores','Q','',10);e('pool','scores','pooled K');
  m('weights','Head weights projection',ip+'.weights_proj',535,425,'投影结果乘 32⁻½；不做 softmax。head 权重与 ReLU scores 加权求和。','blue');
  d('reduce','Aggregate 32 index heads',`[1, ${T}, ${P}]`,280,525,'weights.unsqueeze(-2) @ scores → squeeze。','blue');e('scores','reduce');e('weights','reduce');
  d('select','Causal mask → top pools',`top min(32, ${P})`,280,625,'完整池的最后一个 token 对 query 可见，池才是合法候选。非法候选填 float32 最小有限数，不是 -Infinity；选后再次剔除无效池。','blue');e('reduce','select');
  d('expand','Expand pools → raw positions',`[1, ${T}, ${Math.min(32,P)*4}]`,280,725,'每个池映射回 4 个原始 token 位置；无效池所有位置写成 -1。','blue');e('select','expand');
  d('tail','Append visible tail + padding',`[1, ${T}, 131] · int32`,280,825,'按每个 query 的可见前缀补最多 3 个不完整池尾 token。其余槽填 -1；输出固定 128+3 宽度。','blue');e('expand','tail');
  m('out',`Layer ${dl} indexer · actual output`,ip,280,925,'真实模块边界的输出；完整索引列表见状态页。','blue');e('tail','out');
  note=`这是 DSA Layer ${dl} 的索引器内部解释；KDA 层没有这个模块。源码实际未调用 indexer RoPE。完整中间形状可在 ATen 页面搜索 indexer，节点标签中的 P 已按本例的缓存长度计算。`;
 }else if(state.sub==='mhc'){
  m('hc','Attention mHC · input / outputs',p+'.attn_hc',280,25,'此图拆解 attention mHC。FFN mHC 算法相同但参数独立，可在单层图选择它。','purple');
  m('rms','Flatten 4×128 → RMS',p+'.attn_hc.input_norm',280,125,'不带可学习权重的 RMSNorm；内部转 FP32。','purple');d('linear','F.linear → 24 mixing logits',`[1, ${T}, 24]`,280,225,'不是 nn.Linear 子模块；算子页可定位 aten.linear 与参数 fn。','purple');e('hc','rms','input streams');e('rms','linear');
  d('pre','pre · sigmoid + ε',`[1, ${T}, 4]`,25,325,'前 4 维，经专用 scale 和 base 后生成 collapse 权重。','purple');d('post','post · 2×sigmoid',`[1, ${T}, 4]`,280,325,'接下来 4 维，经自己的 scale 和 base；决定子层输出写入每一路的权重。','purple');d('comb','comb · reshape 4×4',`[1, ${T}, 4, 4]`,535,325,'最后 16 维，经自己的 scale 和 base；决定 residual streams 之间混合。','purple');e('linear','pre');e('linear','post');e('linear','comb');
  d('collapse','Weighted stream sum',S,25,525,'collapsed=Σstream pre×X；不要求 pre 的和为 1。','purple');d('sink','Sinkhorn normalization',`[1, ${T}, 4, 4]`,535,425,'softmax+ε → column norm → 19 轮 row/column norm。对应 sinkhorn_iters=20；用实际算子可查看每轮细节。','purple');e('pre','collapse');e('comb','sink');
  d('sub','RMSNorm → Attention',S,25,625,'主干层图展示实际子层；mHC 不改变该子层的 hidden_size。');e('collapse','sub');d('mix','Recombine streams',H,280,725,'post 与归一化 comb 直接在 mHC hook 的输出 0、1 中可查看。','purple','Xnew = post[..., :, None] × sublayer[..., None, :]\n     + comb.transpose(-1, -2) @ X');e('post','mix','post');e('sink','mix','combᵀ');e('sub','mix','sublayer');
  note='图中 CODE 节点为源码级解释，其内部中间值没有假造。真实 mHC 模块记录包含三个输出，底层每个运算的 tensor ID 与形状可追踪。';
 }else if(state.sub==='ffn'){
  if(state.layer<3){m('gate','Gate projection',p+'.mlp.gate_proj',25,60);m('up','Up projection',p+'.mlp.up_proj',535,60);m('act','SiLU',p+'.mlp.act_fn',25,180);d('mul','Elementwise product',S,280,300,'SiLU(gate_proj(x)) × up_proj(x)。本 tiny intermediate_size=128。','amber');m('down','Down projection',p+'.mlp.down_proj',280,420);e('gate','act');e('act','mul');e('up','mul');e('mul','down');}
  else{m('router','Router · FP32 linear',p+'.mlp.gate',25,25,'模块返回原始 logits、最终 weights、expert IDs。实际顺序以右侧输入输出为准；“状态与路由”展示每个 token 的选择。','amber');d('sig','sigmoid + correction bias',`[${T},32]`,25,125,'sigmoid(logits) 作为基础权重；correction bias 只影响选谁，不参与最终聚合权重。','amber');d('top','Select 8 of 32',`IDs / weights [${T},8]`,25,225,'本配置 n_group=1。取 top-8；从未加 bias 的 sigmoid scores gather，再归一化并乘 2.5。','amber');m('experts','Routed experts · grouped MM',p+'.mlp.experts',25,425,'每个入选专家执行 gate/up → clamp → SiLU(gate)×up → down；按 token 的路由权重聚合。具体分组、索引与矩阵乘在 ATen 中完整记录。','amber');m('shared','Shared expert · always active',p+'.mlp.shared_experts',535,225,'独立门控 MLP；不占用 top-8 的位置，不乘路由系数。','amber');m('out','Routed sum + shared output',p+'.mlp',280,625,'输出再进入 FFN mHC 的 residual recombine。','amber');e('router','sig');e('sig','top');e('top','experts','weights × 2.5');e('experts','out');e('shared','out','independent path');d('clamp','Expert gated activation',`hidden 128 → intermediate 128`,280,325,'gate 上界截到 10；up 截到 [-10,10]；之后 SiLU(gate)×up。','amber','e(x) = Wdown[ SiLU(clamp(Wgate x,max=10))\n                  × clamp(Wup x,−10,10) ]');e('clamp','experts','expert computation');}
  note='分支共享同一归一化层输入。MoE 选中权重之和约为 2.5；这里不是 softmax router，也不能把 shared expert 算入 top-8。';
 }else{
  m('head','HyperHead · mean over streams',base+'.hc_head',280,25,'四路输出取均值；不是可学习的加权和。','purple');m('norm','Final RMSNorm',base+'.norm',280,125);d('slice','Select last position','[1, 1, 128]',280,225,'logits_to_keep=1：prefill 也只保留最后位置用于下一 token 预测。');m('lm','LM head · linear 128 → 154880','lm_head',280,325);d('argmax','Greedy argmax','[1] → '+phase().chosen.id,280,425,'从原始 logits 选择最大项。右侧概率用完整词表 softmax 算出，仅用于解释，不参与随机采样。','amber');d('next',state.step===3?'停止：达到 4 token':'作为下一次 decode 的输入',state.step===3?'max_new_tokens = 4':`input_ids = [[${phase().chosen.id}]]`,280,525,state.step===3?'最后生成 token 没有再次送入模型，所以已处理缓存长度仍为 21，完整文本长度为 22。':'缓存已包含本轮输入。新 token 在下一轮才进入 embedding 和缓存；不要提前计入本轮缓存。','state');['head','norm','slice','lm','argmax','next'].forEach((id,i,a)=>{if(i)e(a[i-1],id);});
  note='Prefill 已经产生第 1 个新 token；Decode 1 接收它，并产生第 2 个。最后一轮停止后，末尾新 token 尚未写入缓存。';
 }
 return {nodes,edges,note,height:Math.max(...nodes.map(n=>n.y+n.h))+35};
}
function drawGraph(spec){const lookup=new Map(spec.nodes.map(n=>[n.id,n]));return `<svg viewBox="0 0 780 ${spec.height}" role="img" aria-label="${esc(state.sub)} 数据流"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="#6c919e"/></marker></defs>${spec.edges.map(ed=>{const a=lookup.get(ed.a),b=lookup.get(ed.b);let x1=a.x+a.w/2,y1=a.y+a.h,x2=b.x+b.w/2,y2=b.y;let path,labelx=(x1+x2)/2,labely=(y1+y2)/2-7;if(ed.via!==null){const channel=ed.via<390?10:770,side=channel<a.x?'left':'right';x1=a.x+(side==='right'?a.w:0);y1=a.y+a.h/2;path=`M${x1},${y1} H${channel} V${y2-16} H${x2} V${y2}`;labelx=channel<390?55:725;labely=(y1+y2)/2;}else{const mid=(y1+y2)/2;path=`M${x1},${y1} C${x1},${mid} ${x2},${mid} ${x2},${y2}`;}return `<path class="flow-edge ${ed.style?'state-edge':''}" d="${path}"/>${ed.label?`<text class="flow-label" x="${labelx}" y="${labely}" text-anchor="middle">${esc(ed.label)}</text>`:''}`;}).join('')}${spec.nodes.map(n=>`<g class="flow-node ${n.color} ${state.node===n.id?'selected':''}" data-node="${n.id}" tabindex="0" role="button" aria-label="${esc(n.title)}"><rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="8"/><text class="flow-title" x="${n.x+13}" y="${n.y+24}">${esc(n.title)}</text><text class="flow-shape" x="${n.x+13}" y="${n.y+44}">${esc(n.sh)}</text><text class="node-status ${n.ref?'':'derived'}" x="${n.x+n.w-10}" y="${n.y+57}" text-anchor="end">${n.ref?'TRACE':'CODE'}</text></g>`).join('')}</svg>`;}
function renderGraph(){
 const spec=graphSpec();graphNodes=spec.nodes;if(!spec.nodes.some(n=>n.id===state.node))state.node=spec.nodes[0].id;
 const names={overview:'完整前向',layer:'单层',attention:'Attention',indexer:'DSA indexer',mhc:'mHC',ffn:'FFN',output:'生成 token'};
 $('#view').innerHTML=`<div class="view-toolbar"><div><h2>${phaseName(state.step)} · ${state.sub==='overview'?'从输入到输出':`Layer ${state.layer} / ${kind(state.layer)}`}</h2><p>T = 本轮输入 ${phase().input_ids.length} · L = 可见上下文 ${phase().context_length} · 点击节点查看真实张量</p></div>${layerSelect()}</div><div class="graph-layout"><section class="panel"><div class="graph-tools">${Object.entries(names).map(([k,v])=>`<button data-sub="${k}" class="${state.sub===k?'active':''}">${v}</button>`).join('')}</div><div class="graph-canvas">${drawGraph(spec)}</div><div class="diagram-foot">${spec.note}<br><span class="tag measured">TRACE</span> 实际模块／函数采样　<span class="tag math">CODE</span> 源码语义解释，值未采样</div></section><aside class="panel inspector" id="node-inspector"></aside></div>`;showNode();
}
function showNode(){const n=graphNodes.find(n=>n.id===state.node),r=n.ref;document.querySelectorAll('[data-node]').forEach(el=>el.classList.toggle('selected',el.dataset.node===n.id));const inputs=r?.input_samples||r?.inputs||[],outputs=r?.output_samples||r?.outputs||[];
 $('#node-inspector').innerHTML=`<div class="inspect-head">${tag(r?'真实执行记录':'源码解释',r?'measured':'math')}<h3>${esc(n.title)}</h3><div class="inspect-path">${esc(r?.path||r?.scope||'形状来自执行配置与源码')}</div></div><div class="inspect-body"><p>${esc(n.desc||'点击下方查看实际输入输出及对应算子。')}</p>${n.formula?`<div class="formula">${esc(n.formula)}</div>`:''}${r?`<div class="io-shape">ATen #${r.op_start}–${r.op_end-1} · ${r.op_end-r.op_start} events</div><button class="inspection-action" id="node-ops">查看对应算子 →</button>${inputs.filter(x=>typeof x==='object').map((s,i)=>`<details ${i===0?'open':''}><summary>INPUT ${i}</summary>${sampleCard(s,'IN '+i)}</details>`).join('')}${outputs.filter(x=>typeof x==='object').map((s,i)=>`<details ${i===0?'open':''}><summary>OUTPUT ${i}</summary>${sampleCard(s,'OUT '+i)}</details>`).join('')}`:`<div class="inactive-branch">此节点用于解释函数内部数据流；未保存其完整数值。查看所属模块及 ATen 序列可确认实际输入输出形状。</div>`}${r?.kwargs?`<details><summary>函数 keyword inputs / options</summary>${Object.entries(r.kwargs).map(([k,v])=>v&&typeof v==='object'&&v.shape?sampleCard(v,esc(k)):`<div class="op-args">${esc(k)} = ${esc(JSON.stringify(v))}</div>`).join('')}</details>`:''}${state.sub==='output'?logits():''}</div>`;
 if(r)$('#node-ops').onclick=()=>{state.range=[r.op_start,r.op_end];state.scope='';state.search='';state.page=0;state.op=r.op_start;setTab('ops');};
}
function logits(){const s=phase();return `<div class="io-block"><div class="io-caption">下一 token · TOP 10 LOGITS</div><div class="logit-list">${s.top_tokens.map((t,i)=>`<div class="logit-row ${i===0?'chosen':''}" title="ID ${t.id}; logit ${t.logit}; full-vocab probability ${t.probability}"><span>${esc(t.text)}</span><div class="logit-track"><div class="logit-fill" style="width:${t.probability/s.top_tokens[0].probability*100}%"></div></div><span class="logit-value">${(t.probability*100).toFixed(5)}%</span></div>`).join('')}</div><div class="heat-caption">条长相对 top-1；百分比来自全部 154,880 项的 softmax，未对 top-10 重新归一化。实际选择为 argmax。</div></div>`;}
function querySelect(id){const s=phase();return `<select id="${id}" aria-label="选择查询 token">${s.position_ids.map((pos,i)=>`<option value="${i}" ${i===state.query?'selected':''}>q${i} · position ${pos}</option>`).join('')}</select>`;}
function renderState(){
 const s=phase(),after=s.cache_after.find(c=>c.layer===state.layer),before=s.cache_before.find(c=>c.layer===state.layer),isK=kind(state.layer)==='KDA';
 const ml=Math.max(3,state.layer),dl=[3,7].includes(state.layer)?state.layer:3;
 const router=s.routers[`${base}.layers.${ml}.mlp.gate`],ids=router.selected[state.query],weights=router.weights[state.query];
 const att=s.attention[`${base}.layers.${dl}.self_attn`],indices=s.indexers[`${base}.layers.${dl}.self_attn.indexer`][0][state.query];
 const cacheRows=Object.entries(after.tensors).map(([name,t])=>{const b=before?.tensors[name];return `<tr><td><code>${esc(name)}</code></td><td><div class="shape-transition">${b?shape(b.shape):'∅ 未初始化'}<br>↓<br>${shape(t.shape)}</div></td><td><code>${t.dtype}<br>${(t.numel*4/1024).toLocaleString(undefined,{maximumFractionDigits:1})} KiB</code></td><td><code>${b?fmt(b.norm):'—'} → ${t.numel?fmt(t.norm):'empty'}</code></td></tr>`;}).join('');
 $('#view').innerHTML=`<div class="view-toolbar"><div><h2>观察状态如何跨 token 保留</h2><p>本轮 position ${s.position_ids[0]}${s.position_ids.length>1?'–'+s.position_ids.at(-1):''} · 缓存已经处理 ${s.context_length} 个 token</p></div>${layerSelect()}</div><div class="state-grid">${panel(`Layer ${state.layer} · ${kind(state.layer)} cache`, `<div class="cache-list">${Array.from({length:8},(_,i)=>`<button class="cache-layer ${i===state.layer?'active':''}" data-cache-layer="${i}">L${i} ${kind(i)}</button>`).join('')}</div><div class="table-scroll"><table class="state-table"><thead><tr><th>状态</th><th>Before → After</th><th>当前容量</th><th>L2 norm</th></tr></thead><tbody>${cacheRows}</tbody></table></div><p class="state-annotation">${isK?'conv_states 保存最近 4 个位置的原始投影 QKV；recurrent_states 保存压缩历史的 FP32 状态。两者大小固定，但内容每步更新。':'keys 保存 normalized compressed latent；values 的最后一维为 0，是空 RoPE key 分量。indexer_keys 的 257=key128 + gate128 + validity1；这些缓存随 L 增长。此处不把缓存命名 values 误解释成 attention 的展开 V。'}</p><details><summary>缓存数值 · Before / After 采样</summary>${Object.entries(after.tensors).map(([name,t])=>`<h4>${esc(name)}</h4><div class="state-grid"><div>${before?.tensors[name]?sampleCard(before.tensors[name],'BEFORE'):'<p class="muted">未初始化</p>'}</div><div>${sampleCard(t,'AFTER')}</div></div>`).join('')}</details>`,tag('真实缓存'),'full-width')}
 ${panel(`MoE · Layer ${ml} · 每个 token 的专家选择`,`<div class="router-token"><span>32 个专家，选 8 个${state.layer<3?' · 当前层是 Dense，参考 L3':''}</span>${querySelect('router-query')}</div><div class="router-grid">${router.sigmoid_scores[state.query].map((score,e)=>{const j=ids.indexOf(e);return `<div class="expert-cell ${j>=0?'selected':''}" title="expert ${e}; logit=${router.logits[state.query][e]}; sigmoid=${score}; routed weight=${j>=0?weights[j]:0}">E${String(e).padStart(2,'0')}<small>${j>=0?weights[j].toFixed(3):'—'}</small></div>`;}).join('')}</div><div class="formula">sigmoid(logits) + bias → top-8 IDs\nweights = selected sigmoid scores / Σselected × 2.5\n实际 Σweights = ${weights.reduce((a,b)=>a+b,0).toFixed(7)}</div><div class="inactive-branch">+ 1 个 shared expert，始终独立执行；不包含在紫色 8 个专家中。</div><p class="legend-note">方格数字是最终路由权重；悬停可查看原始 logit / sigmoid score。权重只描述本次随机模型计算，不表示专家语义。</p>`,tag('完整路由记录'))}
 ${panel(`DSA · Layer ${dl} · raw token indices`,`<div class="router-token"><span>Query position ${s.position_ids[state.query]}</span>${querySelect('index-query')}</div><div class="index-grid">${indices.map((v,i)=>`<span class="index-chip ${v<0?'invalid':''}" title="slot ${i} → ${v}">${v}</span>`).join('')}</div><p class="legend-note">共 ${indices.length} 槽，${indices.filter(x=>x>=0).length} 个有效索引。-1 是无效占位，不是对最后一个 token 的 Python 索引。池大小 4；不完整尾部按因果可见性补入。本短 prompt 很短，通常所有历史 token 都能覆盖。</p><p class="state-annotation">${state.layer!==dl?`当前层是 KDA；此面板明确展示 DSA Layer ${dl}。`:''}</p>`,tag('完整索引记录'))}
 ${panel(`DSA · Layer ${dl} · Attention head 0`,`${heatmap(att.head0,'行 = 本轮 query，列 = 全上下文 key；head 0 完整矩阵')}<p class="state-annotation">完整 attention 张量 ${shape(att.shape)}。这里只保留 head 0 的全部值；其余 63 个 head 未保存完整数值。prefill 呈因果三角形；decode 只有一行。</p>`,tag('真实 attention'))}
 ${panel('本轮输出 → 下一轮输入',`<div class="tensor-preview">本轮 input_ids = ${shape(s.input_ids)}<br>logits = ${shape(s.logits_shape)}<br>argmax = ${s.chosen.id} (${esc(JSON.stringify(s.chosen.text))})<br>${state.step===3?'停止：4 个新 token 已生成；末尾 token 未再入缓存。':`下一轮 input_ids = [[${s.chosen.id}]]<br>下一轮 position = ${s.context_length}`}</div>${logits()}<div class="inactive-branch">mHC streams 为当前前向激活，不跨 decode 保存。Vision / MTP 本次均未执行。</div>`,tag('自回归衔接'))}</div>`;
}
async function getOps(i){if(!opCache.has(i)){opCache.set(i,fetch(`trace/ops-${i}.json`).then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json();}).catch(e=>{opCache.delete(i);throw e;}));}return opCache.get(i);}
async function renderOps(){const step=state.step;$('#view').innerHTML='<div class="panel panel-body">正在载入本轮 ATen 记录…</div>';try{const data=await getOps(step);if(state.tab!=='ops'||state.step!==step)return;drawOps(data);}catch(e){if(state.tab==='ops')$('#view').innerHTML=`<div class="panel panel-body error">算子记录加载失败：${esc(e.message)}。切换标签可以重试。</div>`;}}
function filteredOps(data){return data.events.filter(e=>(!state.scope||e.scope===state.scope||e.scope.startsWith(state.scope+'.'))&&(!state.search||`${e.op} ${e.scope}`.toLowerCase().includes(state.search.toLowerCase()))&&(!state.range||(e.id>=state.range[0]&&e.id<state.range[1])));}
function drawOps(data){
 const scopes=[...new Set(data.events.map(e=>e.scope))].sort();
 $('#view').innerHTML=`<div class="view-toolbar"><div><h2>算子显微镜 · ${phaseName(state.step)}</h2><p>${data.events.length.toLocaleString()} 个 ATen dispatch events · 输入 / 输出 ID、形状、dtype、常量与参数名</p></div><a class="download" href="trace/ops-${state.step}.json" download>完整 JSON ↓</a></div><div class="operator-controls"><input id="op-search" aria-label="搜索算子" placeholder="搜索，如 matmul / topk / layers.3" value="${esc(state.search)}"><select id="op-scope" aria-label="选择模块范围"><option value="">全部模块</option>${scopes.map(s=>`<option value="${esc(s)}" ${state.scope===s?'selected':''}>${esc(s.replace(base+'.',''))}</option>`).join('')}</select><button id="clear-op-filter">清除筛选${state.range?' / 节点范围':''}</button></div><div class="operator-layout"><section class="panel"><div id="op-count" class="operator-count"></div><div id="op-list" class="operator-list"></div><div class="diagram-foot">按真实发生顺序排列。ATen 是框架调度层，不是 GPU 指令；一个 ATen 运算可封装多个底层操作。v 是记录器的数据流版本，标记同一 tensor 对象再次返回；跨对象共享 storage 的别名写入不做完整追踪。</div></section><aside class="panel inspector" id="op-inspector"></aside></div>`;
 $('#op-search').oninput=e=>{state.search=e.target.value;state.page=0;refreshOps(data);};$('#op-scope').onchange=e=>{state.scope=e.target.value;state.range=null;state.page=0;refreshOps(data);};$('#clear-op-filter').onclick=()=>{state.search='';state.scope='';state.range=null;state.page=0;drawOps(data);};refreshOps(data);
}
function refreshOps(data){const all=filteredOps(data),per=120;state.page=Math.min(state.page,Math.max(0,Math.ceil(all.length/per)-1));const page=all.slice(state.page*per,(state.page+1)*per);if(!all.some(e=>e.id===state.op))state.op=page[0]?.id??-1;
 $('#op-count').innerHTML=`<span>${all.length.toLocaleString()} 条${state.range?` · #${state.range[0]}–${state.range[1]-1}`:''} · 第 ${state.page+1} / ${Math.max(1,Math.ceil(all.length/per))} 页</span><div><button id="ops-prev" ${state.page===0?'disabled':''}>←</button> <button id="ops-next" ${(state.page+1)*per>=all.length?'disabled':''}>→</button></div>`;
 $('#op-list').innerHTML=page.map(e=>`<button class="op-row ${e.id===state.op?'selected':''}" data-op="${e.id}"><span class="op-num">#${e.id}</span><div><div class="op-name">${esc(e.op)}</div><div class="op-scope">${esc(e.scope.replace(base+'.',''))} · ${e.inputs.length} in → ${e.outputs.length} out</div></div></button>`).join('')||'<div class="panel-body muted">没有符合条件的算子。</div>';
 $('#ops-prev').onclick=()=>{state.page--;refreshOps(data);$('#op-list').scrollTop=0;};$('#ops-next').onclick=()=>{state.page++;refreshOps(data);$('#op-list').scrollTop=0;};document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>{state.op=Number(b.dataset.op);showOp(data);document.querySelectorAll('[data-op]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.op)===state.op));});showOp(data);
}
function showOp(data){const e=data.events[state.op];if(!e){$('#op-inspector').innerHTML='<div class="panel-body muted">选择一个算子。</div>';return;}
 function refs(ids,versions,input){return ids.map((id,i)=>{const t=data.tensors[id];let producer=-1;if(input){for(let j=e.id-1;j>=0;j--){const q=data.events[j];if(q.outputs.some((out,k)=>out===id&&q.output_versions[k]===versions[i])){producer=j;break;}}}return `<button class="tensor-ref" ${producer>=0?`data-producer="${producer}"`:''} ${producer<0?'disabled':''}>${esc(id)} · v${versions[i]} · ${shape(t.shape)}<small>${esc(t.dtype)}${t.parameter?' · parameter: '+esc(t.parameter):''}</small><small>${input?(producer>=0?`← 来自 #${producer} · 点击追溯`:'外部输入 / 参数 / 此版本无前序生产者'):'本算子输出；这里只保存元信息'}</small></button>`;}).join('');}
 $('#op-inspector').innerHTML=`<div class="inspect-head">${tag('ATen · #'+e.id)}<h3>${esc(e.op)}</h3><div class="inspect-path">${esc(e.scope)}</div></div><div class="inspect-body"><div class="io-caption">INPUTS</div>${refs(e.inputs,e.input_versions,true)}<div class="io-block"><div class="io-caption">OUTPUTS</div>${refs(e.outputs,e.output_versions,false)}</div><div class="io-caption">CONSTANT ARGUMENTS</div><pre class="op-args">${esc(JSON.stringify(e.arguments,null,2))}</pre><div class="io-caption">KWARGS</div><pre class="op-args">${esc(JSON.stringify(e.kwargs,null,2))}</pre><p class="heat-caption">arguments 中 null 是被提取的 tensor 占位；实际 tensor 引用见上方。未保存每个算子的完整数值。参数只记录名称与形状，不包含权重值。</p></div>`;
 document.querySelectorAll('[data-producer]').forEach(b=>b.onclick=()=>{state.op=Number(b.dataset.producer);state.scope='';state.range=null;state.search='';state.page=Math.floor(state.op/120);drawOps(data);document.querySelector(`[data-op="${state.op}"]`)?.scrollIntoView({block:'nearest'});});
}
function renderVerify(){
 $('#view').innerHTML=`<div class="verification-grid">${panel('哪些内容被真实记录？',`<div class="check-row"><span class="check-icon">✓</span><div>18 个输入 token，原生 chat template，4 步前向与 4 个新 token。每步 ${trace.steps[0].modules.length} 次模块调用；${trace.steps.reduce((n,s)=>n+s.op_count,0).toLocaleString()} 个 ATen 事件。</div></div><div class="check-row"><span class="check-icon">✓</span><div>模块／函数输入输出的真实 shape、dtype 与全张量统计；采样保存前 24 个值、leading 8×12 tile、末行前 24 个值。路由、索引及 head 0 attention 完整保存。</div></div><div class="check-row"><span class="check-icon">✓</span><div>带记录器与不带记录器的相同 cached 路径：4 步 logits 最大绝对差均为 0。说明采集没有改变该执行路径的结果。</div></div><div class="check-row warn"><span class="check-icon">!</span><div>cached 路径与完整序列重算的数值一致性未通过。token argmax 相同，不等于 logits 数值等价。</div></div>`,tag('验证分项展示'))}
 ${panel('执行条件与边界',`<div class="source-code">${esc(trace.backend)}<br>PyTorch ${esc(trace.torch)}<br>Transformers ${esc(trace.transformers)}<br>use_cache=true · logits_to_keep=1<br>generation=greedy · max_new_tokens=4</div><p class="state-annotation">原 checkpoint 的 FP8 权重在载入时反量化，再将所有参数转 FP32。这里的数值属于这一 CPU 参考后端，不是原生 FP8 GPU 后端结果，不用于性能评估。</p><p class="state-annotation">页面是静态回放，不支持任意 prompt 的在线推理。Vision、MTP、训练与反向传播没有执行。MTP 的 26 个辅助键被当前加载器忽略；主干没有缺失权重。</p><p class="state-annotation">TRACE 表示真实边界采样，CODE 表示源码解释。所有 ATen 事件都有元信息；并没有保存每个 tensor 的每个元素。</p>`,tag('reference backend','math'))}
 <section class="verification-warning full-width"><strong>上游 checkpoint 问题：专家 FP8 尺度被重复量化覆盖</strong><p>权重文件中 576 个 routed-expert scale tensor、9,216 个元素全部为 1.0；其余量化尺度约为 0.000119–0.000225。模型卡的构造脚本先对拆分后的专家权重 pack，随后对所有二维 .weight 再 pack，覆盖了第一次的尺度。专家权重因此达到 ±448，明显放大 FP32 舍入误差。</p><p>诊断中首个 MoE 前的差异约 1.7×10⁻⁶，经过该 MoE 后约为 1.55。专家 top-8 集合与 DSA 索引一致。没有修改权重，也没有猜测丢失的原尺度。当前记录是这个已发布 checkpoint 的真实参考执行；不能作为数值稳定性通过的例子。</p><a href="${checkpoint}README.md#L203" target="_blank" rel="noreferrer">查看上游构造脚本 ↗</a> · <a href="trace/numerical-audit.json" download>下载诊断摘要 ↓</a></section>
 ${panel('逐步数值检查',`<div class="table-scroll"><table class="state-table"><thead><tr><th>阶段</th><th>采集 / 未采集</th><th>Cached / full 最大差</th><th>allclose</th><th>argmax</th></tr></thead><tbody>${trace.steps.map(s=>`<tr><td>${phaseName(s.index)}</td><td>${s.verification.uninstrumented_cached_max_abs}</td><td><code>${fmt(s.verification.max_abs_logit_difference)}</code></td><td>${s.verification['allclose_rtol1e-3_atol1e-4']?tag('PASS'):tag('FAIL','warn')}</td><td>${s.verification.same_argmax?'相同':'不同'}</td></tr>`).join('')}</tbody></table></div><p class="heat-caption">allclose: rtol=1e-3, atol=1e-4；未为掩盖误差放宽阈值。</p>`,tag('独立重算'),'full-width')}
 ${panel('可追溯来源',`<div class="source-code">CHECKPOINT REVISION<br>${trace.revision}<br><br>IMPLEMENTATION SHA256<br>${trace.implementation_sha256}</div><p><a href="${checkpoint}config.json" target="_blank" rel="noreferrer">Pinned config ↗</a> · <a href="${checkpoint}README.md" target="_blank" rel="noreferrer">模型卡与生成脚本 ↗</a></p><p><a href="https://github.com/huggingface/transformers/blob/v5.20.2/src/transformers/models/glm5_next/modeling_glm5_next.py" target="_blank" rel="noreferrer">执行实现 ↗</a></p><p class="state-annotation">复现脚本 capture_trace.py 随源仓库保存；权重仅在临时环境下载，不进入页面或源码仓库。</p>`,tag('版本固定'))}
 ${panel('本轮未执行的分支',`<div class="inactive-branch">Vision encoder：输入没有 image tensors，因此没有视觉 patch、视觉 attention 或 projector 激活。</div><div class="inactive-branch">MTP：普通逐 token 自回归，没有 speculative decoding 或多 token 辅助预测。</div><div class="inactive-branch">最终 stop：达到 max_new_tokens=4；不是 EOS。输出字符串包含随机拼接文本，不能用于评估语言能力。</div><p class="state-annotation">基模与 tiny 的层数、维度、权重数值不同；当前数值记录只属于指定 tiny checkpoint。</p>`,tag('未执行','inactive'))}</div>`;
}
document.addEventListener('click',e=>{
 const t=e.target.closest('[data-tab]');if(t){setTab(t.dataset.tab);return;}
 const s=e.target.closest('[data-step]');if(s){setPhase(Number(s.dataset.step));return;}
 const l=e.target.closest('[data-layer]');if(l){state.layer=Number(l.dataset.layer);state.sub='layer';state.node=null;setTab('graph');return;}
 const c=e.target.closest('[data-cache-layer]');if(c){state.layer=Number(c.dataset.cacheLayer);renderState();return;}
 const sub=e.target.closest('[data-sub]');if(sub){state.sub=sub.dataset.sub;state.node=null;renderGraph();return;}
 const n=e.target.closest('[data-node]');if(n){state.node=n.dataset.node;showNode();return;}
 const token=e.target.closest('[data-token]');if(token){state.token=Number(token.dataset.token);document.querySelectorAll('[data-token]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.token)===state.token));showToken();}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-node]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',e=>{if(e.target.id==='layer-select'){state.layer=Number(e.target.value);state.node=null;if(state.sub==='overview')state.sub='layer';render();}if(['router-query','index-query'].includes(e.target.id)){state.query=Number(e.target.value);renderState();}});
$('#previous-step').onclick=()=>setPhase(state.step-1);$('#next-step').onclick=()=>setPhase(state.step+1);$('#prepare-nav').onclick=()=>setPhase(-1);
fetch('trace/session.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json();}).then(data=>{trace=data;render();}).catch(e=>{$('#view').innerHTML=`<div class="panel panel-body error">执行记录无法载入：${esc(e.message)}。请通过 HTTP 服务器打开页面。</div>`;});
